// Block (composition) — an interactive calendar paired with the selected date's agenda.
// Calendar owns date behavior; Stack owns arrangement and Separator owns the agenda division.
import { getLocalTimeZone, parseDate, today } from "@internationalized/date";
import { useState } from "react";
import type { Ref } from "react";
import type { DateValue } from "react-aria-components";
import { Calendar } from "../components/Calendar";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./CalendarView.css";

export interface CalendarViewProps {
  events?: { date: string; title: string }[];
  onDateChange?: (date: string) => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function CalendarView({ events = [], onDateChange, className, ref }: CalendarViewProps) {
  const [selectedDate, setSelectedDate] = useState<DateValue>(() =>
    events[0]?.date ? parseDate(events[0].date) : today(getLocalTimeZone()),
  );
  const selectedDateString = selectedDate.toString();
  const selectedEvents = events.filter((event) => event.date === selectedDateString);

  const handleChange = (date: DateValue) => {
    setSelectedDate(date);
    onDateChange?.(date.toString());
  };

  return (
    <Stack
      as="section"
      ref={ref}
      direction={{ small: "column", medium: "row" }}
      gap="large"
      align="start"
      aria-label="Calendar and agenda"
      className={className ? `sd-calendarview ${className}` : "sd-calendarview"}
    >
      <Calendar aria-label="Choose a date" value={selectedDate} onChange={handleChange} />
      <Stack gap="small" className="sd-calendarview__agenda">
        <>
          <h2 className="sd-calendarview__heading sd-type-title-medium">
            Agenda for {selectedDateString}
          </h2>
        </>
        <Separator />
        {selectedEvents.length > 0 ? (
          <Stack as="ul" gap="small" className="sd-calendarview__events">
            {selectedEvents.map((event, index) => (
              <li key={`${event.date}-${event.title}-${index}`} className="sd-type-body-medium">
                {event.title}
              </li>
            ))}
          </Stack>
        ) : (
          <>
            <p className="sd-calendarview__empty sd-type-caption-medium">No events scheduled.</p>
          </>
        )}
      </Stack>
    </Stack>
  );
}

.sd-calendarview {
  width: 100%;
}

.sd-calendarview__agenda {
  flex: 1;
  min-width: 0;
  width: 100%;
}

.sd-calendarview__heading,
.sd-calendarview__empty {
  margin: 0;
}

.sd-calendarview__events {
  margin: 0;
  padding-inline-start: var(--sd-space-large);
}
